import { describe, it } from "vitest";

describe("quote premium (newcomer, first contract: base + 10% first insurance + 5 G fee)", () => {
  it.todo("empty item list -> premium 5 G (only the processing fee)");
  it.todo("plain sword -> 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("plain amulet -> 71 G (60 base + 6 + 5)");
  it.todo("plain staff -> 93 G (80 base + 8 + 5)");
  it.todo("plain potion -> 49 G (40 base + 4 + 5)");
  it.todo("1 rune -> 33 G (25 base + 2.5 + 5 = 32.5, rounded up in MHPCO's favor)");
  it.todo("1 moonstone -> 33 G (25 base component premium)");
  it.todo("2 runes -> 60 G (50 base)");
  it.todo("3 runes -> 71 G (60 base, block applies)");
  it.todo("4 runes -> 115 G (100 base, no block: block requires exactly 3)");
  it.todo("7 runes -> 198 G (175 base -> 197.5 rounded up)");
  it.todo("2 runes + 1 moonstone -> 88 G (75 base, no block: different types; 87.5 rounded up)");
  it.todo("3 runes + 3 moonstones -> 137 G (120 base, two separate blocks)");
});

describe("premium modifiers", () => {
  it.todo("newcomer with cursed steel sword enchantment 3 -> 165 G (100 + 50 curse + 10 first + 5 fee)");
  it.todo("cursed sword + plain amulet -> 231 G (curse adds 50 % of sword base only: 160 + 50 + 16 first + 5 fee)");
  it.todo("sword with exactly enchantment 5 -> 145 G (100 + 30 high enchantment + 10 + 5)");
  it.todo("sword with enchantment 4 -> 115 G (no high-enchantment surcharge)");
  it.todo("cursed sword with exactly enchantment 5 -> 195 G (both surcharges: 100 + 50 + 30 + 10 + 5)");
  it.todo("cursed sword with enchantment 4 -> 165 G (only curse surcharge)");
  it.todo("customer with exactly 2 years -> loyalty discount: plain sword 95 G (100 - 20 + 10 + 5)");
  it.todo("customer with 1 year -> no loyalty discount: plain sword 115 G");
  it.todo("second quote of a 0-year customer -> follow-up discount: plain sword 100 G (100 + 10 - 15 + 5)");
  it.todo("3-year customer's second quote, cursed steel sword enchantment 7 -> 160 G");
});

describe("claim payout", () => {
  it.todo("regular steel sword enchantment 3, damage 500 -> payout 400, remainingCap 1600");
  it.todo("rune, damage 200 -> payout 100, remainingCap 400 (rune insured at 250 G)");
  it.todo("dragon-material sword enchantment exactly 8, damage 1000 -> payout 400");
  it.todo("dragon-material sword enchantment 9, damage 1000 -> payout 400 (50 % rule wins)");
  it.todo("dragon-material sword enchantment 5, damage 800 -> payout 700 (full reimbursement)");
  it.todo("steel sword enchantment 9, damage 1000 -> payout 400 (50 % first, then deductible)");
  it.todo("steel sword enchantment 9, damage 901 -> payout 350 (350.5 rounded down in MHPCO's favor)");
  it.todo("sword (500) and amulet (300) damaged in one event -> payout 600, remainingCap 2600 (deductible per damaged item)");
  it.todo("two swords both damaged by 500 -> payout 800, remainingCap 3200 (cap 4000)");
});

describe("insurance sum and cap", () => {
  it.todo("amulet, damage 200 -> payout 100, remainingCap 1100 (amulet insured at 600 G)");
  it.todo("staff, damage 200 -> payout 100, remainingCap 1500 (staff insured at 800 G)");
  it.todo("potion, damage 200 -> payout 100, remainingCap 700 (potion insured at 400 G)");
  it.todo("moonstone, damage 200 -> payout 100, remainingCap 400 (moonstone insured at 250 G)");
  it.todo("cursed sword, damage 500 -> remainingCap 1600 (cap from unmodified insurance value 1000)");
  it.todo("sword + 3 runes (block), sword damage 500 -> payout 400, remainingCap 3100 (insurance sum 1750)");
  it.todo("sword, two successive claims of 1500 -> payouts 1400 then 600, remainingCap 600 then 0");
});

