    const item = items.find((insured) => insured.type === damage.itemType);
    return sum + damage.amount * reimbursementPercent(item) - DEDUCTIBLE * PERCENT;
  }, 0);
  const payout = Math.floor(payoutInPercentOfG / PERCENT);
  return { payout, remainingCap: cap - payout };
}
