import type { Damage, Item } from "./claimOffice.js";
import { insuranceSum } from "./priceList.js";

const CAP_FACTOR = 2;
const DEDUCTIBLE = 100;
const HIGH_ENCHANTMENT_LEVEL = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
const PERCENT = 100;

export type Settlement = { payout: number; remainingCap: number };
export type Policy = { items: Item[]; remainingCap: number };

function reimbursementPercent(item: Item | undefined): number {
  return (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT : PERCENT;
}

function damagePayoutInPercentOfG(damage: Damage, item: Item | undefined): number {
  return damage.amount * reimbursementPercent(item) - DEDUCTIBLE * PERCENT;
}

export function openPolicy(items: Item[]): Policy {
  return { items, remainingCap: insuranceSum(items) * CAP_FACTOR };
}

export function settleClaim(policy: Policy, damages: Damage[]): Settlement {
  const payoutInPercentOfG = damages.reduce(
    (sum, damage) => sum + damagePayoutInPercentOfG(damage, policy.items.find((insured) => insured.type === damage.itemType)),
    0,
  );
  const payout = Math.min(Math.floor(payoutInPercentOfG / PERCENT), policy.remainingCap);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}
import { openPolicy, type Policy, settleClaim } from "./claim.js";
import { quotePremium } from "./premium.js";

export type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
export type Damage = { itemType: string; amount: number };
export type QuoteStep = { op: "quote"; items: Item[] };
export type ClaimStep = { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
export type Scenario = { customer: { yearsWithMHPCO: number }; steps: (QuoteStep | ClaimStep)[] };
export type Result = { premium: number } | { payout: number; remainingCap: number };

export function runScenario(scenario: Scenario): { results: Result[] } {
  let previousContracts = 0;
  const policies = new Map<number, Policy>();
  const results = scenario.steps.map((step, index): Result => {
    if (step.op === "claim") {
      return settleClaim(policies.get(step.policy) ?? openPolicy([]), step.incident.damages);
    }
    const customer = { yearsWithMHPCO: scenario.customer.yearsWithMHPCO, previousContracts };
    previousContracts += 1;
    policies.set(index, openPolicy(step.items));
    return { premium: quotePremium(step.items, customer) };
  });
  return { results };
}

